import{_ as a,o as s,c as e,ag as r}from"./chunks/framework.DXGyWiRo.js";const o="/assets/image.Dp9wkfo0.webp",n="/assets/image-1._x9IEXEL.webp",i="/assets/image-2.Dw4IE3gQ.webp",l="/assets/image-3.D1Vo-okP.webp",d="/assets/image-4.C1X9dJuh.webp",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/ESP-IDF-getting-started/13 SPI显示模块渲染屏幕/13.2 为什么用SPI及如何用/index.md","filePath":"tutorials/ESP-IDF-getting-started/13 SPI显示模块渲染屏幕/13.2 为什么用SPI及如何用/index.md","lastUpdated":null}'),p={name:"tutorials/ESP-IDF-getting-started/13 SPI显示模块渲染屏幕/13.2 为什么用SPI及如何用/index.md"};function h(c,t,g,S,u,P){return s(),e("div",null,[...t[0]||(t[0]=[r(`<div class="article-meta-card"><div class="meta-left"><div class="title-line"><span>📜 本文许可</span><a href="http://www.apache.org/licenses/LICENSE-2.0" target="_blank" class="license-badge">Apache 2.0</a></div><div class="info-line"><span>© 2026 门主引擎 · 创始人：Mooooo</span><span>·</span><a href="https://space.bilibili.com/283444330" target="_blank">📺 Bilibili</a><a href="https://v.douyin.com/kcQ2Ofh6SiA/" target="_blank">🎵 Douyin</a><a href="/about/" target="_blank">💬 公众号</a><span>· 联系：<a href="mailto:itsntcool@qq.com">📧 邮箱</a></span></div></div><div class="meta-right"><a href="/products/" class="shop-btn"> 🚀 觉醒计划 · 配套硬件 </a></div></div><h2 id="spi-通信协议-从零开始的逐步认知" tabindex="-1">SPI 通信协议：从零开始的逐步认知 <a class="header-anchor" href="#spi-通信协议-从零开始的逐步认知" aria-label="Permalink to &quot;SPI 通信协议：从零开始的逐步认知&quot;">​</a></h2><p>你好！你已经了解了屏幕模块的基本知识，现在我们来深入理解 SPI 通信协议。我会按照四个问题的步骤，一步一步带你认识它。</p><h2 id="整体的通信并控制屏幕显示的数据流向过程-单向" tabindex="-1">整体的通信并控制屏幕显示的数据流向过程（单向） <a class="header-anchor" href="#整体的通信并控制屏幕显示的数据流向过程-单向" aria-label="Permalink to &quot;整体的通信并控制屏幕显示的数据流向过程（单向）&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ESP32-S3（你的代码）</span></span>
<span class="line"><span>    ↓ SPI总线（SCLK + MOSI）</span></span>
<span class="line"><span>ST7789V2（屏幕控制芯片）</span></span>
<span class="line"><span>    ↓ 内部GRAM（显存）</span></span>
<span class="line"><span>TFT液晶面板（你看到的画面）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><img src="`+o+'" alt="从 ESP32-S3 到 TFT 面板"></p><hr><h3 id="_1-为什么要用-spi-背景" tabindex="-1">1. 为什么要用 SPI？（背景） <a class="header-anchor" href="#_1-为什么要用-spi-背景" aria-label="Permalink to &quot;1. 为什么要用 SPI？（背景）&quot;">​</a></h3><h4 id="问题的起点-单片机怎么-说话-给屏幕听" tabindex="-1">问题的起点：单片机怎么&quot;说话&quot;给屏幕听？ <a class="header-anchor" href="#问题的起点-单片机怎么-说话-给屏幕听" aria-label="Permalink to &quot;问题的起点：单片机怎么&quot;说话&quot;给屏幕听？&quot;">​</a></h4><p>你的 ESP32-S3 是一个&quot;大脑&quot;，ST7789V2 是屏幕的&quot;控制芯片&quot;。它们是两个独立的芯片，要让屏幕显示内容，大脑必须把指令和数据&quot;传递&quot;给屏幕控制芯片。</p><p>这就需要一种<strong>通信协议</strong>——就像两个人说话要用同一种语言一样。</p><h4 id="为什么不用其他方式" tabindex="-1">为什么不用其他方式？ <a class="header-anchor" href="#为什么不用其他方式" aria-label="Permalink to &quot;为什么不用其他方式？&quot;">​</a></h4><p>常见的通信方式有很多，比如：</p><table tabindex="0"><thead><tr><th>接口类型</th><th>数据线数量</th><th>速度</th><th>适合场景</th></tr></thead><tbody><tr><td><strong>SPI</strong></td><td>1根（或多根）数据线</td><td><strong>快</strong></td><td>屏幕、Flash、传感器</td></tr><tr><td>I2C</td><td>1根数据线</td><td>中等</td><td>传感器、小屏幕</td></tr><tr><td>I80（并行）</td><td>8或16根数据线</td><td>更快</td><td>大屏幕</td></tr><tr><td>RGB</td><td>更多数据线</td><td>最快</td><td>高分辨率大屏</td></tr></tbody></table><p>[<a href="https://docs.espressif.com/projects/esp-iot-solution/zh_CN/latest/display/lcd/lcd_guide.html#id4" target="_blank" rel="noreferrer">LCD接口对比</a>]</p><p>你的 240×320 TFT 屏幕用的是 <strong>SPI 接口</strong>，原因很简单：</p><ul><li><strong>引脚少</strong>：只需要 4~5 根线（SCLK、MOSI、CS、DC，加上可选的 MISO），节省 IO 资源。</li><li><strong>速度够用</strong>：对于 240×320 这种分辨率的小屏幕，SPI 的速度完全够用。</li><li><strong>硬件支持好</strong>：ESP32-S3 内置了 SPI 控制器（GP-SPI2、GP-SPI3），硬件直接支持，不需要软件模拟。</li></ul><p>[<a href="https://documentation.espressif.com/esp32-s3_technical_reference_manual_cn.html" target="_blank" rel="noreferrer">ESP32-S3 SPI控制器</a>]</p><p><img src="'+n+'" alt="为什么选择 SPI"></p><hr><h3 id="_2-spi-的技术原理是什么" tabindex="-1">2. SPI 的技术原理是什么？ <a class="header-anchor" href="#_2-spi-的技术原理是什么" aria-label="Permalink to &quot;2. SPI 的技术原理是什么？&quot;">​</a></h3><h4 id="spi-的全称" tabindex="-1">SPI 的全称 <a class="header-anchor" href="#spi-的全称" aria-label="Permalink to &quot;SPI 的全称&quot;">​</a></h4><p>SPI = <strong>Serial Peripheral Interface</strong>（串行外设接口），是一种<strong>同步串行通信协议</strong>。</p><h4 id="核心概念-主机与从机" tabindex="-1">核心概念：主机与从机 <a class="header-anchor" href="#核心概念-主机与从机" aria-label="Permalink to &quot;核心概念：主机与从机&quot;">​</a></h4><ul><li><strong>主机（Master）</strong>：发起通信的一方，就是你的 ESP32-S3。</li><li><strong>从机（Slave）</strong>：被动响应的一方，就是你的 ST7789V2 屏幕控制芯片。</li></ul><h4 id="四根核心信号线" tabindex="-1">四根核心信号线 <a class="header-anchor" href="#四根核心信号线" aria-label="Permalink to &quot;四根核心信号线&quot;">​</a></h4><p>SPI 通信靠这几根线完成：</p><table tabindex="0"><thead><tr><th>引脚名</th><th>你的接线</th><th>作用</th></tr></thead><tbody><tr><td><strong>SCLK</strong>（时钟）</td><td>GPIO 12</td><td>ESP32-S3 发出节拍，每个节拍传一位数据</td></tr><tr><td><strong>MOSI</strong>（主出从入）</td><td>GPIO 11</td><td>ESP32-S3 → 屏幕，发送数据</td></tr><tr><td><strong>CS</strong>（片选）</td><td>GPIO 10</td><td>拉低 = 选中屏幕，开始通信</td></tr><tr><td><strong>DC</strong>（数据/命令）</td><td>GPIO 14</td><td>高电平=数据，低电平=命令</td></tr><tr><td>RST（复位）</td><td>GPIO 13</td><td>硬件复位屏幕</td></tr><tr><td>BL（背光）</td><td>GPIO 9</td><td>控制背光亮灭</td></tr></tbody></table><p>[<a href="https://docs.espressif.com/projects/esp-iot-solution/zh_CN/latest/display/lcd/lcd_guide.html#id4" target="_blank" rel="noreferrer">SPI接口引脚说明</a>]</p><h4 id="通信过程-用大白话解释" tabindex="-1">通信过程（用大白话解释） <a class="header-anchor" href="#通信过程-用大白话解释" aria-label="Permalink to &quot;通信过程（用大白话解释）&quot;">​</a></h4><p>想象你在餐厅点菜：</p><ol><li><strong>CS 拉低</strong> → 你举手叫服务员（选中屏幕，告诉它&quot;我要跟你说话了&quot;）</li><li><strong>DC 拉低</strong> → 你说&quot;我要点菜&quot;（告诉屏幕接下来是<strong>命令</strong>，比如&quot;设置显示区域&quot;）</li><li><strong>SCLK 产生时钟</strong> → 服务员开始计时，每个节拍你说一个字</li><li><strong>MOSI 传数据</strong> → 你一位一位地说出命令内容</li><li><strong>DC 拉高</strong> → 你说&quot;菜的具体内容是...&quot;（告诉屏幕接下来是<strong>数据</strong>，比如颜色值）</li><li><strong>CS 拉高</strong> → 你说完了，服务员离开（结束本次通信）</li></ol><p>这就是 SPI 的 <strong>4-line 模式</strong>（4线模式），也是你的屏幕使用的模式。</p><p>[<a href="https://docs.espressif.com/projects/esp-iot-solution/zh_CN/latest/display/lcd/spi_lcd.html" target="_blank" rel="noreferrer">4-line模式说明</a>]</p><blockquote><p><strong>关键理解</strong>：DC 引脚是 SPI LCD 特有的！它区分&quot;命令&quot;和&quot;数据&quot;。没有它，屏幕不知道你发的是控制指令还是像素颜色。</p></blockquote><p><img src="'+i+'" alt="SPI 四根核心信号线"></p><p><img src="'+l+'" alt="SPI 四根核心信号线2"></p><hr><h3 id="_3-用了之后会有什么结果" tabindex="-1">3. 用了之后会有什么结果？ <a class="header-anchor" href="#_3-用了之后会有什么结果" aria-label="Permalink to &quot;3. 用了之后会有什么结果？&quot;">​</a></h3><p>当你完成以上步骤后：</p><ol><li><strong>BL（GPIO9）拉高</strong> → 背光亮起，屏幕发光（但还没有内容）</li><li><strong>RST 复位</strong> → ST7789V2 芯片重置到初始状态</li><li><strong>SPI 发送初始化命令</strong> → 告诉屏幕：分辨率是 240×320，颜色格式是 RGB565，方向是竖屏...</li><li><strong>发送像素数据</strong> → 通过 MOSI 线，把每个像素的颜色值（16位 RGB565）一位一位传给屏幕</li><li><strong>屏幕显示内容</strong> → ST7789V2 把收到的颜色数据写入内部 GRAM（显存），屏幕就显示出对应颜色</li></ol><p><img src="'+d+'" alt="SPI 驱动结果"></p><hr><h3 id="总结-一句话理解-spi" tabindex="-1">总结：一句话理解 SPI <a class="header-anchor" href="#总结-一句话理解-spi" aria-label="Permalink to &quot;总结：一句话理解 SPI&quot;">​</a></h3><blockquote><p><strong>SPI 就是 ESP32-S3 用一根时钟线打节拍、一根数据线逐位传数据、一根CS线选中屏幕、一根DC线区分命令和数据，从而控制 ST7789V2 显示内容的通信方式。</strong></p></blockquote><p>它的优点是<strong>引脚少、速度快、硬件支持好</strong>，非常适合你这种 240×320 的小屏幕应用场景。[<a href="https://docs.espressif.com/projects/esp-iot-solution/zh_CN/latest/display/lcd/spi_lcd.html" target="_blank" rel="noreferrer">SPI LCD驱动流程</a>]</p>',46)])])}const I=a(p,[["render",h]]);export{m as __pageData,I as default};
